// Deklarasi variabel
const $tabelData = $('#tabelData'),
    $formData = $('#formData'),
    $modalDiv = $('#modalDiv'),
    formCek = CirebonwebForm.FormCek($formData);

if (typeof $.validator !== 'undefined') {
    $.validator.addMethod('dimensiBahan', function (value, element) {
        let nilai = Number(String(value).replace(',', '.')),
            nilaiMinimum = $('#rumus').val() === '1' ? 0.01 : 0;

        return this.optional(element) || (!Number.isNaN(nilai) && nilai >= nilaiMinimum);
    }, 'Nilai harus 0 atau lebih; saat rumus = 1 minimal 0,01.');
}

/**
 * Logika Utama Kalkulasi dan Pengaturan UI Form Bahan
 */
function aturKonsepBahan() {
    let valRumus = $('#rumus').val(),
        lebarVal = parseFloat($('#lebar').val().replace(',', '.')) || 0,
        panjangVal = parseFloat($('#panjang').val().replace(',', '.')) || 0,
        $isiPaket = $('#isi_paket'),
        satuan1Val = $('#satuan_1').val() || '',
        satuan2Val = $('#satuan_2').val() || '';

    // 1. Update text append pada input luas
    $('.satuan1').text(satuan1Val);

    // 2. Handling berdasarkan Rumus
    if (valRumus === "0") {
        // Mode: Perkalian Luas (Hitung Otomatis)
        $isiPaket.prop('readonly', true);
        let totalLuas = lebarVal * panjangVal;
        $isiPaket.val(totalLuas);
    } else {
        // Mode: Perkalian Qty (Input Manual oleh User)
        $isiPaket.prop('readonly', false);
    }

    // 3. Update Label Satuan 2 (Format: "1 [satuan_2] = [luas/qty] [satuan_1]")
    let luasVal = $isiPaket.val() || 0;
    $('.satuan2').text(`1 ${satuan2Val} = ${luasVal} ${satuan1Val}`);
}

// DataTables
$(function () {
    $tabelData.DataTable({
        processing: true,
        serverSide: true,
        ajax: {
            url: `${thisUrl}/tabel`,
            type: 'POST',
            data: function (d) {
                d.filter_tipe = $('#filter_tipe').val();
            }
        },
        autoWidth: false,
        responsive: true,
        search: { return: true },
        dom: 'Blfrtip',
        buttons: [
            { text: 'Add', action: () => { simpan(); } },
            {
                text: 'Reload',
                action: function (e, dt, node, config) {
                    dt.search('').draw();
                    $('#filter_tipe').val('').trigger('change');
                    Swal.fire({ icon: 'success', title: 'Informasi', text: 'Selesai reload tabel ke kondisi awal', showConfirmButton: false, timer: 1300 })
                        .then(function () { dt.ajax.reload(null, true); });
                }
            },
            {
                extend: 'excelHtml5',
                exportOptions: { columns: ':not(.no-export)' }
            }
        ],
        columnDefs: [
            { targets: '_all', className: 'dt-head-center' },
            { targets: [4, 5, 6], className: 'dt-body-right' },
            { targets: [0, 2, 11], className: 'dt-body-center' },
            { targets: [9, 10], render: function (data, type, row) { return CirebonwebFormat.Tanggal(data, 'waktu') } },
            { targets: 11, orderable: false },
        ]
    });

    // Custom dropdown filter
    $('#tabelData_filter.dataTables_filter').append($('#filter_tipe'));
    $(document).on('change', '#filter_tipe', function () {
        $tabelData.DataTable().ajax.reload(null, false);
    });

    // Modal Event Listeners (Auto focus search Select2)
    // $(document).on('select2:open', () => document.querySelector('.select2-container--open .select2-search__field')?.focus());

    // Event Listener Realtime Perubahan Form
    $('#rumus, #satuan_1, #satuan_2').on('change', function () {
        aturKonsepBahan();
    });

    $('#lebar, #panjang, #isi_paket').on('input change', function () {
        aturKonsepBahan();
    });

    // Reset Modal Event
    $modalDiv.on('shown.bs.modal', function () {
        $('.select2').select2({ tags: true, dropdownParent: $modalDiv });

        // Jalankan sinkronisasi UI saat modal terbuka
        aturKonsepBahan();
        formCek.resetInitial();
    }).on('hidden.bs.modal', function () {
        CirebonwebForm.FormReset(this);
        $('.select2.select2-hidden-accessible').select2('destroy');

        // Reset label ke tampilan awal
        $('.satuan2').text('1 roll = 0 m²');
        $('.satuan1').text('m²');
    });
});

// Form Submit (Insert/Update)
function simpan(id) {
    let $modalTitle = $('.modal-title'),
        $btnSubmit = $('#btnSubmit'),
        postUrl = `${thisUrl}/simpan`;

    // Tentukan URL POST: Simpan atau Update
    if (id > 0) {
        CirebonwebForm.FormFetch(`${thisUrl}/getid`, { id }, 'POST', {})
            .done(function (response) {
                if (response.success) {
                    $modalTitle.text('Edit Data');
                    $btnSubmit.text('Update');

                    // Populate Data
                    $formData.find('#id').val(response.data.id);
                    $formData.find('#mesin_tipe_id').val(response.data.mesin_tipe_id);
                    $formData.find('#nama').val(response.data.nama);
                    $formData.find('#kode').val(response.data.kode);
                    $formData.find('#gsm').val(response.data.gsm);
                    $formData.find('#isi_paket').val(CirebonwebFormat.Desimal(response.data.isi_paket));
                    $formData.find('#lebar').val(CirebonwebFormat.Desimal(response.data.lebar));
                    $formData.find('#panjang').val(CirebonwebFormat.Desimal(response.data.panjang));

                    // Trigger Select2
                    $formData.find('#satuan_1').val(response.data.satuan_1);
                    $formData.find('#satuan_2').val(response.data.satuan_2);
                    $formData.find('#rumus').val(response.data.rumus);

                    $modalDiv.modal('show');
                }
            });
    } else {
        $modalTitle.text('Tambah Data');
        $btnSubmit.text('Simpan');
        $modalDiv.modal('show');
    }

    // Form Validasi
    $formData.validate($.extend(CirebonwebForm.FormValidasi(), {
        rules: {
            mesin_tipe_id: { required: true, digits: true },
            nama: { required: true, minlength: 3, maxlength: 30 },
            kode: { required: true, minlength: 2, maxlength: 5 },
            gsm: { required: true, digits: true, maxlength: 3 },
            lebar: { required: true, maxlength: 8, dimensiBahan: true },
            panjang: { required: true, maxlength: 8, dimensiBahan: true },
            isi_paket: { required: true, maxlength: 10 },
            rumus: { required: true, digits: true },
            satuan_1: { required: true, maxlength: 10 },
            satuan_2: { required: true, maxlength: 10 },
        },
        submitHandler: function () {
            if (!formCek.isChanged()) return false;
            CirebonwebForm.FormFetch(postUrl, $formData.serializeArray(), 'POST', {
                before_call: function () {
                    if (!formCek.isChanged()) return false;
                    $btnSubmit.attr('disabled', true).html('<span class="spinner-border spinner-border-sm mr-1"></span> Loading...');
                },
                after_call: function () { $btnSubmit.attr('disabled', false).html('Simpan'); }
            })
                .done(function (response) {
                    if (!response.success) return;
                    $modalDiv.modal('hide');
                    Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                        .then(function () { $tabelData.DataTable().ajax.reload(null, false); });
                });
            return false;
        }
    }));
}

// Form Submit (Delete)
function hapus(id) {
    Swal.fire({
        title: 'Konfirmasi',
        html: 'Apakah yakin ingin menghapus data ini? <br> Data akan dihapus secara permanen!',
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        confirmButtonText: 'Ya, hapus!'
    }).then(function (result) {
        if (!result.isConfirmed) return;
        CirebonwebForm.FormFetch(`${thisUrl}/hapus`, { id }, 'POST', {}).done(function (response) {
            if (!response.success) return;
            Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                .then(function () { $tabelData.DataTable().ajax.reload(null, false); });
        });
    });
}